    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08/P[0], 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1/P[1], 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06/P[2], 2.3],
