  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + primeGrid(sx,sy)*0.35 + Math.sin((sx+sy)*0.12+t*2.5)*0.15;
